import csv,json,collections
from pathlib import Path
base=Path('Temp/DifficultyAudit')
settings=json.loads((base/'static-settings.json').read_text(encoding='utf-8'))
rows=[]
for batch in ['main1','main2']:
    p=base/batch/'results.csv'
    if p.exists():
        with p.open(encoding='utf-8-sig',newline='') as f:
            for r in csv.DictReader(f):
                if not r.get('errors'):continue
                for k in ['stage','seed','fps','passed','limit','kills','towers','skills','errors']:r[k]=int(r[k])
                for k in ['delay','elapsed']:r[k]=float(r[k])
                r['clear']=r['clear'].lower()=='true'
                rows.append(r)
def result(r):return ('クリア' if r['clear'] else f'{r["elapsed"]:.2f}秒で敗北')+f'（通過{r["passed"]}/{r["limit"]}）'
def baseline(p,s):return [r for r in rows if r['stage']==s and r['policy']==p and r['delay']==5 and r['fps']==60 and '-Normal' not in r['id']]
def rate(v):return f'{sum(r["clear"] for r in v)}/{len(v)}' if v else '未完了'
text=['# 現行版の難易度監査（作業中）','', 'この文書は進行中のデータから生成した暫定版。最終結論は全試行と追加の条件切り分けが終わってから確定する。','', '## 検証条件','',f'- 現在{len(rows)}試行、実行時エラー{sum(r["errors"] for r in rows)}件。', '- 現在のUnity 6000.2.7f2上で、実際のStage_1シーン・13経路・10か所のNode・物理判定・弾・敵プールを使用。', '- 通常条件は毎フレーム1/60秒の固定刻み、ゲーム速度1.0。描画と操作を受け付けない開始カウントダウンのみ省略。HP・資金・報酬・ウェーブ・設置上限は変更しない。', '- 建設・強化は既存の購入／強化処理を呼ぶ自動操作。人間のマウス操作、説明映像による理解度、新規ユーザーのクリア率は実測していない。', '- 乱数種は17／101／2027。初期値を固定して再現性を確保するが、戦闘が分岐の時刻を変えるため、手順の違う試行で到来列が完全に同一になるわけではない。', '- セーブ進行・ハイスコア・速度設定は検証前を保存し、各バッチ終了時に復元。ゲームの元ファイルはSHA-256で変更されていないことを確認。','', '## 基本条件の実測','', '表はクリア回数／試行回数。これは指定した固定乱数での観測値であり、人間一般の成功確率ではない。','', '| 操作手順 | 1限 | 2限 | 3限 | 4限 | 5限 | 6限 |','|---|---:|---:|---:|---:|---:|---:|']
labels={'InitialNormal':'通常3基を5・7・9秒で設置、その後放置','InitialMixed':'通常→黄色→通常を5・7・9秒で設置、その後放置','ReactiveNormal':'通常を増設・強化','ReactiveMixed':'通常と黄色を交互に増設・強化','ReactiveMixedSkill':'混成の増設・強化＋臨時休講','SkillOnly':'設置せず21秒前後の臨時休講のみ'}
for p in labels:text.append('|'+labels[p]+'|'+'|'.join(rate(baseline(p,s)) for s in range(1,7))+'|')
text+=['', '増設・強化の手順：GOから5秒後に開始し2秒ごとに建設か強化を1回。まず4基まで配置、次にそれぞれLv2、以後は解放地点への増設を優先し、残りで低Lvの塔を強化する。混成は通常／黄色交互。臨時休講は使用可能かつ生存敵6体以上で発動する。雨、2番目の技能、売却・再配置はこの比較では使っていない。','', '## 1限目の操作猶予と配置差','', '| 条件ID | 結果 |','|---|---|']
for r in rows:
    if r['stage']==1 and ('-Normal' in r['id'] or r['policy'] in ['InitialNormal','InitialMixed','SkillOnly']):text.append(f'| {r["id"]} | {result(r)} |')
text+=['', 'Node番号は監査で用いた解放順。1=中央右、2=中央左、3=右端、4=左端。初期の4地点から3地点を選ぶ条件を比較している。','', '## 2限目と3限目の逆転の確認','', '| 乱数 | 通常中心・2限 | 通常中心・3限 |','|---|---|---|']
for seed in [17,101,2027]:
    pair=[]
    for s in [2,3]:
        v=[r for r in baseline('ReactiveNormal',s) if r['seed']==seed]
        pair.append(result(v[0]) if v else '未完了')
    text.append(f'|{seed}|'+'|'.join(pair)+'|')
text+=['', '乱数17の操作ログでは、2限の4基目は17.017秒、最初の強化は23.016秒。3限では4基目11.000秒、最初の強化17.017秒。2限と3限は未強化通常弾でともに5発必要だが、初期資金は100円と120円で差がある。開始時の20円が、早い4基目→撃破報酬→強化の連鎖に影響している。資金以外にもウェーブ数値・解放閾値が異なるため、初期資金だけが唯一の原因とはこの比較だけでは断定しない。','', '## HP倍率と実際の攻撃回数','', '| 時限 | HP | 未強化通常の必要弾数 | 未強化黄色の必要弾数 | 初期金 | 通過による敗北 | 制限時間 | 設置上限 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for d in settings:text.append(f'|{d["stage"]}|{d["hp"]:.1f}|{d["normalShots"][0]}|{d["yellowFirstShots"][0]}|{d["money"]:.0f}円|{d["loss"]:.0f}人に到達|{d["time"]:.0f}秒|{d["maxTowers"]:.0f}'+('（全10地点）' if d['maxTowers']==0 else '')+'|')
text+=['', 'HPは8.0→8.6→9.2→9.8→10.4→11.0と等間隔でも、攻撃回数は等間隔ではない。1→2限で通常が4発から5発、4→5限で通常が5発から6発・黄色が1発から2発になる。単独の黄色タワーでは5限で一撃撃破を失い、必要な攻撃が倍になる。','', '黄色Lv2は直撃9.92、Lv3は11.52。5・6限ではLv2にしても直撃の必要回数は2発のままで、Lv3で初めて一撃に戻る。貫通・範囲・攻撃間隔の強化は別途入るため「強化が無効」という意味ではない。','', '## 6限目だけ残るウェーブの段差','', '- 1〜5限はwaveSpawnRampCount=4、6限はフィールド未設定の既定値0。6限だけ、次のウェーブへの間隔補間が無効。', '- 6限の第1波は平均0.475秒間隔、第2波は平均0.205秒間隔。切り替え時の出現頻度が約2.32倍になる。5限の対応する目標間隔比は約1.62倍で、さらに最初の数体で補間される。', '- 6限は5限から、HP増・制限時間70→90秒・敗北人数30→25・設置上限8→7が同時に変わる。','', '## 説明と実際の条件の不一致','', '- 6限の説明は「一人も通さなければ、今日の勝ち」。実際は25人目で敗北するので、24人までは通っても90秒に到達すればクリアできる。説明を文字通り読むと条件を誤解する。', '- 全30ウェーブは同じPedestrianを参照しており、敵の移動速度は全時限で3。難化の中心は別の敵種の学習ではなく、HP・物量・損失許容数・経済・設置制限。', '- SkillBarは技能名・キー・費用を表示するが、PlayerSkill.descriptionを表示していない。臨時休講の全体30ダメージ・無料・30秒再使用が、そのボタンだけでは読み取れない。ステージ紹介映像の理解しやすさは今回未評価。','', '## 判断の限界','', '- 3つの固定乱数と有限の手順で「誰でも」「どんな状況でも」を証明することはできない。1限の基本配置でクリアできることと、初見の人間がその操作を理解して実行できることは別の検証。', '- 自動操作の敗北は、他の戦術でもクリア不能であることを意味しない。雨、教授の急病、異なる設置順、売却再配置、技能を温存する戦術などは別途あり得る。', '- 紙上の最大DPSは射程・移動・被弾停止・散開・過剰ダメージ・着弾前の敵消失・経済循環を含まないため、それだけで黄色の強さや全体難易度の適否は判定しない。','']
(base/'report-draft.md').write_text('\n'.join(text),encoding='utf-8')
print('draft rows',len(rows))